    res=[]; seen=set()
    for r in range(H):
        for c in range(W):
            if i[r][c]==bg or (r,c) in seen: continue
            col=i[r][c]; p=(r,c)
            s=None
            for dr,dc in [(-1,-1),(1,-1)]:
                pr,pc=p[0]+dr,p[1]+dc
                if not(0<=pr<H and 0<=pc<W) or i[pr][pc]!=col:
                    s=(dr,dc); break
            else: s=(1,1)
            run=[p]; q=p+s
            while 0<=q[0]<H and 0<=q[1]<W and i[q[0]][q[1]]==col:
                run.append(q); q+=s
            bb=p-s
            while 0<=bb[0]<H and 0<=bb[1]<W and i[bb[0]][bb[1]]==col:
                run.insert(0,bb); bb-=s
            res.append((col,tuple(run),s))
            seen.update(run)
    return res
