    h,w=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    out=[r[:] for r in g]
    cells=[(r,c,g[r][c]) for r in range(h) for c in range(w) if g[r][c]!=bg]
    runs=[]
    for v,ps in {(v):p for p,v_ in cells}.items() if False else {}: pass
    byc={}
    for r,c,v in cells: byc.setdefault(v,[]).append((r,c))
    D=[(1,1),(1,-1)]
    def chains(ps,keyf,step):
        lines={}
        for p in ps: lines.setdefault(keyf(p),[]).append(p)
        res=[]
        for k,lst in lines.items():
            lst=sorted(lst)
            for i,p in enumerate(lst):
                ch=[p]; used={p}
                q=(p[0]+step[0],p[1]+step[1])
                while q in set(lst):
                    used.add(q); ch.append(q); q=(q[0]+step[0],q[1]+step[1])
                if len(ch)>=2: res.append(tuple(ch))
        return res
    for v,ps in byc.items():
        for step in D:
            runs+=chains(ps,(lambda p:step[0]*p[0]+step[1]*p[1]),step)
        # vertical/horizontal too
        runs+=chains(ps,(lambda p:p[0]),(1,0))
        runs+=chains(ps,(lambda p:p[1]),(0,1))
    for run in runs:
        col=g[run[0][0]][run[0][1]]
        d=(run[-1][0]-run[0][0],run[-1][1]-run[0][1])
        for start,dd in [(run[0],(-d[0],-d[1])),(run[-1],d)]:
            q=start
            while True:
                q=(q[0]+dd[0],q[1]+dd[1])
                if not(0<=q[0]<h and 0<=q[1]<w) or out[q[0]][q[1]]!=bg: break
                # stop if adjacent (8-conn) to a different color original cell
                adj=False
                for sr,sc,vv in [(q2[0],q2[1],g[q2[0]][q2[1]]) for q2,vv in cells]:
                    if vv!=col and abs(sr-q[0])<=1 and abs(sc-q[1])<=1:
                        adj=True; break
                if adj: break
                out[q[0]][q[1]]=col
    return out
